const input=$json.body ?? $json;
const name=String(input.name ?? '').trim();
const email=String(input.email ?? '').trim().toLowerCase();
const company=String(input.company ?? '').trim();
const subject=String(input.subject ?? '').trim();
const message=String(input.message ?? '').trim();
const errors=[];
if(!name) errors.push('name is required');
if(!email || !email.includes('@')) errors.push('valid email is required');
if(!subject) errors.push('subject is required');
if(!message) errors.push('message is required');
if(errors.length) throw new Error(errors.join('; '));
return [{json:{name,email,company,subject,message}}];

const d=$json;
const text=`${d.subject} ${d.message}`.toLowerCase();
const has=(words)=>words.some(w=>text.includes(w));
let categoria='Outros';
if(has(['boleto','cobrança','cobranca','pagamento','fatura','nota fiscal','financeiro','reembolso'])) categoria='Financeiro';
else if(has(['erro','sistema','acesso','senha','integração','integracao','api','fora do ar','não funciona','nao funciona','indisponível','indisponivel'])) categoria='Técnico';
else if(has(['orçamento','orcamento','proposta','plano','preço','preco','contratar','contratação','contratacao','comercial'])) categoria='Comercial';
let prioridade='Baixa';
if(has(['urgente','crítico','critico','fora do ar','parado','produção','producao','bloqueado','não funciona','nao funciona'])) prioridade='Crítica';
else if(has(['hoje','imediato','quanto antes','impacto','erro'])) prioridade='Alta';
else if(has(['dúvida','duvida','ajuda','problema','dificuldade'])) prioridade='Média';
const now=new Date();
const ticket=`SF-${now.getTime().toString().slice(-8)}`;
return [{json:{Ticket:ticket,Nome:d.name,Email:d.email,Empresa:d.company,Assunto:d.subject,Mensagem:d.message,Categoria:categoria,Prioridade:prioridade,Status:'Aberto',CriadoEm:now.toISOString()}}];

